/// Series 'profile' (segmented):
inline constexpr std::string_view profile_series = "profile";

/// One sample of 'profile'. Array fields hold their own dtype and shape;
/// optional fields left empty are not written (stored as NaN / 0).
struct ProfileRow {
    std::int64_t time_ns{0};
    /// x, y, z per point; NaN = no measurement. [m]. shape [points_per_profile, 3]
    Array points{};
    /// shape [points_per_profile]
    std::optional<Array> intensity;
};

/// Many samples of 'profile' as columns (bool as 0/1 bytes; array fields
/// one Array [count, sample shape...]). An empty optional column is not written.
struct ProfileColumns {
    std::vector<std::int64_t> time_ns;
    Array points;
    Array intensity;

    [[nodiscard]] std::size_t size() const { return time_ns.size(); }
    [[nodiscard]] ProfileRow row(std::size_t i) const {
        ProfileRow r;
        r.time_ns = time_ns.at(i);
        r.points = detail::sample_of(points, i);
        if (!intensity.shape().empty() && intensity.shape()[0] > i)
            r.intensity = detail::sample_of(intensity, i);
        return r;
    }
};

/// Appends one sample to a 'profile' writer (SeriesWriter or
/// SegmentedSeriesWriter).
template <class Writer>
void append(Writer& writer, const ProfileRow& r) {
    std::vector<FieldValue> f;
    f.push_back({"points", detail::view_of(r.points)});
    if (r.intensity) f.push_back({"intensity", detail::view_of((*r.intensity))});
    writer.append(r.time_ns, f);
}

/// Appends every sample of `c` at once (SeriesWriter::append_many).
template <class Writer>
void append(Writer& writer, const ProfileColumns& c) {
    std::vector<FieldValue> f;
    f.push_back({"points", detail::view_of(c.points)});
    if (!c.intensity.shape().empty())
        f.push_back({"intensity", detail::view_of(c.intensity)});
    writer.append_many(std::span<const std::int64_t>(c.time_ns), f);
}

/// Samples [start, start + count) of 'profile'; empty when the node has
/// no such series.
[[nodiscard]] inline ProfileColumns read_profile(const NodeReader& node,
                                                 std::uint64_t start = 0,
                                                 std::uint64_t count = all) {
    ProfileColumns c;
    if (!node.has_series("profile")) return c;
    const SeriesReader s = node.series("profile");
    c.time_ns = s.time(start, count);
    {
        Array a = s.read("points", start, count);
        c.points = std::move(a);
    }
    {
        Array a = s.read("intensity", start, count);
        c.intensity = std::move(a);
    }
    return c;
}
/// The same as rows.
[[nodiscard]] inline std::vector<ProfileRow> read_profile_rows(
    const NodeReader& node, std::uint64_t start = 0, std::uint64_t count = all) {
    const ProfileColumns c = read_profile(node, start, count);
    std::vector<ProfileRow> rows;
    rows.reserve(c.size());
    for (std::size_t i = 0; i < c.size(); ++i) rows.push_back(c.row(i));
    return rows;
}

