/// Adds the node `name` under its category.
inline NodeWriter add(ScanWriter& scan, std::string_view name, const Attributes& a) {
    return scan.add_node(name, schema_id, a.to_attributes());
}
/// The attributes of a node of this schema (any version-1 node).
[[nodiscard]] inline Attributes read(const NodeReader& node) {
    return Attributes::from_attributes(node.attributes());
}

/// Series 'objects' (inline): One row per object, in scene order; time = when the scene
/// was written. World = file coordinates times unit and scale, rotated about the mesh's
/// bounding-box centre (X, then Y, then Z, world axes), with that centre moved to
/// position.
inline constexpr std::string_view objects_series = "objects";

/// One sample of 'objects'. Array fields hold their own dtype and shape;
/// optional fields left empty are not written (stored as NaN / 0).
struct ObjectsRow {
    std::int64_t time_ns{0};
    /// Surface taken from a volume: the mesh is in world mm already and the placement is
    /// the identity
    bool from_volume{};
    /// File unit of the mesh: 0 mm, 1 cm, 2 m, 3 inch
    std::uint8_t unit{};
    /// On top of unit
    double scale{};
    /// About the centre, X then Y then Z. [deg]. shape [3]
    std::array<double, 3> rotation{};
    /// Where the bounding-box centre goes, in the scan's world frame. [mm]. shape [3]
    std::array<double, 3> position{};
    /// The material is a formula, not an element
    bool is_compound{};
    /// 0 = the element's own density. [g/cm3]
    double density{};
    /// Part of the simulation
    bool enabled{};
    /// RGB 0..1 in a 3D view. shape [3]
    std::array<float, 3> colour{};
    /// Row of its first vertex in vertices
    std::uint64_t first_vertex{};
    std::uint64_t vertex_count{};
    /// Row of its first triangle in triangles
    std::uint64_t first_triangle{};
    std::uint64_t triangle_count{};
    /// Row of its first point in registration
    std::uint64_t first_registration{};
    std::uint64_t registration_count{};
};

/// Many samples of 'objects' as columns (bool as 0/1 bytes; array fields
/// one Array [count, sample shape...]). An empty optional column is not written.
struct ObjectsColumns {
    std::vector<std::int64_t> time_ns;
    std::vector<std::uint8_t> from_volume;
    std::vector<std::uint8_t> unit;
    std::vector<double> scale;
    std::vector<std::array<double, 3>> rotation;
    std::vector<std::array<double, 3>> position;
    std::vector<std::uint8_t> is_compound;
    std::vector<double> density;
    std::vector<std::uint8_t> enabled;
    std::vector<std::array<float, 3>> colour;
    std::vector<std::uint64_t> first_vertex;
    std::vector<std::uint64_t> vertex_count;
    std::vector<std::uint64_t> first_triangle;
    std::vector<std::uint64_t> triangle_count;
    std::vector<std::uint64_t> first_registration;
    std::vector<std::uint64_t> registration_count;

    [[nodiscard]] std::size_t size() const { return time_ns.size(); }
    [[nodiscard]] ObjectsRow row(std::size_t i) const {
        ObjectsRow r;
        r.time_ns = time_ns.at(i);
        r.from_volume = from_volume[i] != 0;
        r.unit = unit[i];
        r.scale = scale[i];
        r.rotation = rotation[i];
        r.position = position[i];
        r.is_compound = is_compound[i] != 0;
        r.density = density[i];
        r.enabled = enabled[i] != 0;
        r.colour = colour[i];
        r.first_vertex = first_vertex[i];
        r.vertex_count = vertex_count[i];
        r.first_triangle = first_triangle[i];
        r.triangle_count = triangle_count[i];
        r.first_registration = first_registration[i];
        r.registration_count = registration_count[i];
        return r;
    }
};

/// Appends one sample to a 'objects' writer (SeriesWriter or
/// SegmentedSeriesWriter).
template <class Writer>
void append(Writer& writer, const ObjectsRow& r) {
    std::vector<FieldValue> f;
    f.push_back({"from_volume", scalar(r.from_volume)});
    f.push_back({"unit", scalar(r.unit)});
    f.push_back({"scale", scalar(r.scale)});
    f.push_back({"rotation", view(r.rotation.data(), {3})});
    f.push_back({"position", view(r.position.data(), {3})});
    f.push_back({"is_compound", scalar(r.is_compound)});
    f.push_back({"density", scalar(r.density)});
    f.push_back({"enabled", scalar(r.enabled)});
    f.push_back({"colour", view(r.colour.data(), {3})});
    f.push_back({"first_vertex", scalar(r.first_vertex)});
    f.push_back({"vertex_count", scalar(r.vertex_count)});
    f.push_back({"first_triangle", scalar(r.first_triangle)});
    f.push_back({"triangle_count", scalar(r.triangle_count)});
    f.push_back({"first_registration", scalar(r.first_registration)});
    f.push_back({"registration_count", scalar(r.registration_count)});
    writer.append(r.time_ns, f);
}

/// Appends every sample of `c` at once (SeriesWriter::append_many).
template <class Writer>
void append(Writer& writer, const ObjectsColumns& c) {
    std::vector<FieldValue> f;
    f.push_back(
        {"from_volume",
         ConstArrayView{DType::Bool, {c.from_volume.size()}, c.from_volume.data()}});
    f.push_back({"unit", view(c.unit)});
    f.push_back({"scale", view(c.scale)});
    f.push_back({"rotation", view(reinterpret_cast<const double*>(c.rotation.data()),
                                  {c.rotation.size() * 3})});
    f.push_back({"position", view(reinterpret_cast<const double*>(c.position.data()),
                                  {c.position.size() * 3})});
    f.push_back(
        {"is_compound",
         ConstArrayView{DType::Bool, {c.is_compound.size()}, c.is_compound.data()}});
    f.push_back({"density", view(c.density)});
    f.push_back(
        {"enabled", ConstArrayView{DType::Bool, {c.enabled.size()}, c.enabled.data()}});
    f.push_back({"colour", view(reinterpret_cast<const float*>(c.colour.data()),
                                {c.colour.size() * 3})});
    f.push_back({"first_vertex", view(c.first_vertex)});
    f.push_back({"vertex_count", view(c.vertex_count)});
    f.push_back({"first_triangle", view(c.first_triangle)});
    f.push_back({"triangle_count", view(c.triangle_count)});
    f.push_back({"first_registration", view(c.first_registration)});
    f.push_back({"registration_count", view(c.registration_count)});
    writer.append_many(std::span<const std::int64_t>(c.time_ns), f);
}

/// Samples [start, start + count) of 'objects'; empty when the node has
/// no such series.
[[nodiscard]] inline ObjectsColumns read_objects(const NodeReader& node,
                                                 std::uint64_t start = 0,
                                                 std::uint64_t count = all) {
    ObjectsColumns c;
    if (!node.has_series("objects")) return c;
    const SeriesReader s = node.series("objects");
    c.time_ns = s.time(start, count);
    {
        Array a = s.read("from_volume", start, count);
        c.from_volume = detail::bytes_of_bools(a);
    }
    {
        Array a = s.read("unit", start, count);
        c.unit = detail::scalars<std::uint8_t>(a);
    }
    {
        Array a = s.read("scale", start, count);
        c.scale = detail::scalars<double>(a);
    }
    {
        Array a = s.read("rotation", start, count);
        c.rotation = detail::fixed_rows<std::array<double, 3>>(a);
    }
    {
        Array a = s.read("position", start, count);
        c.position = detail::fixed_rows<std::array<double, 3>>(a);
    }
    {
        Array a = s.read("is_compound", start, count);
        c.is_compound = detail::bytes_of_bools(a);
    }
    {
        Array a = s.read("density", start, count);
        c.density = detail::scalars<double>(a);
    }
    {
        Array a = s.read("enabled", start, count);
        c.enabled = detail::bytes_of_bools(a);
    }
    {
        Array a = s.read("colour", start, count);
        c.colour = detail::fixed_rows<std::array<float, 3>>(a);
    }
    {
        Array a = s.read("first_vertex", start, count);
        c.first_vertex = detail::scalars<std::uint64_t>(a);
    }
    {
        Array a = s.read("vertex_count", start, count);
        c.vertex_count = detail::scalars<std::uint64_t>(a);
    }
    {
        Array a = s.read("first_triangle", start, count);
        c.first_triangle = detail::scalars<std::uint64_t>(a);
    }
    {
        Array a = s.read("triangle_count", start, count);
        c.triangle_count = detail::scalars<std::uint64_t>(a);
    }
    {
        Array a = s.read("first_registration", start, count);
        c.first_registration = detail::scalars<std::uint64_t>(a);
    }
    {
        Array a = s.read("registration_count", start, count);
        c.registration_count = detail::scalars<std::uint64_t>(a);
    }
    return c;
}
/// The same as rows.
[[nodiscard]] inline std::vector<ObjectsRow> read_objects_rows(
    const NodeReader& node, std::uint64_t start = 0, std::uint64_t count = all) {
    const ObjectsColumns c = read_objects(node, start, count);
    std::vector<ObjectsRow> rows;
    rows.reserve(c.size());
    for (std::size_t i = 0; i < c.size(); ++i) rows.push_back(c.row(i));
    return rows;
}

