/// Series 'state' (inline): Generator state, one sample per change or at a fixed rate.
inline constexpr std::string_view state_series = "state";

/// One sample of 'state'. Array fields hold their own dtype and shape;
/// optional fields left empty are not written (stored as NaN / 0).
struct StateRow {
    std::int64_t time_ns{0};
    /// 0 off, 1 starting, 2 on, 3 stopping, 4 fault (SourceState.EMISSION_*)
    std::uint8_t emission_state{};
    /// Interlock closed, door shut, key switch on
    bool emission_permitted{};
    /// [kV]
    double voltage_setpoint_kv{};
    /// [uA]
    double current_setpoint_ua{};
    /// [um]
    std::optional<double> focal_spot_um;
    /// Actual value; 0 while emission is off. [kV]
    double voltage_kv{};
    /// Actual value; 0 while emission is off. [uA]
    double current_ua{};
    /// Actual value; 0 while emission is off. [W]
    double power_w{};
    /// [mm]
    std::optional<double> filter_thickness_mm;
};

/// Many samples of 'state' as columns (bool as 0/1 bytes; array fields
/// one Array [count, sample shape...]). An empty optional column is not written.
struct StateColumns {
    std::vector<std::int64_t> time_ns;
    std::vector<std::uint8_t> emission_state;
    std::vector<std::uint8_t> emission_permitted;
    std::vector<double> voltage_setpoint_kv;
    std::vector<double> current_setpoint_ua;
    std::vector<double> focal_spot_um;
    std::vector<double> voltage_kv;
    std::vector<double> current_ua;
    std::vector<double> power_w;
    std::vector<double> filter_thickness_mm;

    [[nodiscard]] std::size_t size() const { return time_ns.size(); }
    [[nodiscard]] StateRow row(std::size_t i) const {
        StateRow r;
        r.time_ns = time_ns.at(i);
        r.emission_state = emission_state[i];
        r.emission_permitted = emission_permitted[i] != 0;
        r.voltage_setpoint_kv = voltage_setpoint_kv[i];
        r.current_setpoint_ua = current_setpoint_ua[i];
        if (i < focal_spot_um.size()) r.focal_spot_um = focal_spot_um[i];
        r.voltage_kv = voltage_kv[i];
        r.current_ua = current_ua[i];
        r.power_w = power_w[i];
        if (i < filter_thickness_mm.size())
            r.filter_thickness_mm = filter_thickness_mm[i];
        return r;
    }
};

/// Appends one sample to a 'state' writer (SeriesWriter or
/// SegmentedSeriesWriter).
template <class Writer>
void append(Writer& writer, const StateRow& r) {
    std::vector<FieldValue> f;
    f.push_back({"emission_state", scalar(r.emission_state)});
    f.push_back({"emission_permitted", scalar(r.emission_permitted)});
    f.push_back({"voltage_setpoint_kv", scalar(r.voltage_setpoint_kv)});
    f.push_back({"current_setpoint_ua", scalar(r.current_setpoint_ua)});
    if (r.focal_spot_um) f.push_back({"focal_spot_um", scalar((*r.focal_spot_um))});
    f.push_back({"voltage_kv", scalar(r.voltage_kv)});
    f.push_back({"current_ua", scalar(r.current_ua)});
    f.push_back({"power_w", scalar(r.power_w)});
    if (r.filter_thickness_mm)
        f.push_back({"filter_thickness_mm", scalar((*r.filter_thickness_mm))});
    writer.append(r.time_ns, f);
}

/// Appends every sample of `c` at once (SeriesWriter::append_many).
template <class Writer>
void append(Writer& writer, const StateColumns& c) {
    std::vector<FieldValue> f;
    f.push_back({"emission_state", view(c.emission_state)});
    f.push_back({"emission_permitted", ConstArrayView{DType::Bool,
                                                      {c.emission_permitted.size()},
                                                      c.emission_permitted.data()}});
    f.push_back({"voltage_setpoint_kv", view(c.voltage_setpoint_kv)});
    f.push_back({"current_setpoint_ua", view(c.current_setpoint_ua)});
    if (!c.focal_spot_um.empty()) f.push_back({"focal_spot_um", view(c.focal_spot_um)});
    f.push_back({"voltage_kv", view(c.voltage_kv)});
    f.push_back({"current_ua", view(c.current_ua)});
    f.push_back({"power_w", view(c.power_w)});
    if (!c.filter_thickness_mm.empty())
        f.push_back({"filter_thickness_mm", view(c.filter_thickness_mm)});
    writer.append_many(std::span<const std::int64_t>(c.time_ns), f);
}

/// Samples [start, start + count) of 'state'; empty when the node has
/// no such series.
[[nodiscard]] inline StateColumns read_state(const NodeReader& node,
                                             std::uint64_t start = 0,
                                             std::uint64_t count = all) {
    StateColumns c;
    if (!node.has_series("state")) return c;
    const SeriesReader s = node.series("state");
    c.time_ns = s.time(start, count);
    {
        Array a = s.read("emission_state", start, count);
        c.emission_state = detail::scalars<std::uint8_t>(a);
    }
    {
        Array a = s.read("emission_permitted", start, count);
        c.emission_permitted = detail::bytes_of_bools(a);
    }
    {
        Array a = s.read("voltage_setpoint_kv", start, count);
        c.voltage_setpoint_kv = detail::scalars<double>(a);
    }
    {
        Array a = s.read("current_setpoint_ua", start, count);
        c.current_setpoint_ua = detail::scalars<double>(a);
    }
    {
        Array a = s.read("focal_spot_um", start, count);
        c.focal_spot_um = detail::scalars<double>(a);
    }
    {
        Array a = s.read("voltage_kv", start, count);
        c.voltage_kv = detail::scalars<double>(a);
    }
    {
        Array a = s.read("current_ua", start, count);
        c.current_ua = detail::scalars<double>(a);
    }
    {
        Array a = s.read("power_w", start, count);
        c.power_w = detail::scalars<double>(a);
    }
    {
        Array a = s.read("filter_thickness_mm", start, count);
        c.filter_thickness_mm = detail::scalars<double>(a);
    }
    return c;
}
/// The same as rows.
[[nodiscard]] inline std::vector<StateRow> read_state_rows(const NodeReader& node,
                                                           std::uint64_t start = 0,
                                                           std::uint64_t count = all) {
    const StateColumns c = read_state(node, start, count);
    std::vector<StateRow> rows;
    rows.reserve(c.size());
    for (std::size_t i = 0; i < c.size(); ++i) rows.push_back(c.row(i));
    return rows;
}

